use std::io::Write;
use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params { width: u32, height: u32 }
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> p: Params;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) { return; }
    let x = id.x;
    let y = id.y;
    let l = select(x - 1u, 0u, x == 0u);
    let r = min(x + 1u, p.width - 1u);
    let u = select(y - 1u, 0u, y == 0u);
    let d = min(y + 1u, p.height - 1u);
    let s = 4u * src[y * p.width + x]
        + src[y * p.width + l] + src[y * p.width + r]
        + src[u * p.width + x] + src[d * p.width + x];
    dst[y * p.width + x] = s / 8u;
}
"#;

fn parse(path: &str) -> Result<(usize, usize, usize, Vec<u32>), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
    let mut it = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        it.next()
            .ok_or_else(|| format!("missing {what}"))?
            .parse::<u64>()
            .map_err(|e| format!("bad {what}: {e}"))
    };
    let w = next("width")? as usize;
    let h = next("height")? as usize;
    let steps = next("steps")? as usize;
    if w == 0 || h == 0 {
        return Err("empty grid".into());
    }
    let mut cells = Vec::with_capacity(w * h);
    for _ in 0..w * h {
        cells.push(next("cell")? as u32);
    }
    Ok((w, h, steps, cells))
}

fn run(path: &str) -> Result<(), String> {
    let (w, h, steps, cells) = parse(path)?;

    let out_cells = if steps == 0 {
        cells
    } else {
        gpu_diffuse(w, h, steps, &cells)?
    };

    let mut out = String::with_capacity(w * h * 8 + 32);
    let mut sum: u64 = 0;
    for row in out_cells.chunks(w) {
        let strs: Vec<String> = row.iter().map(|v| v.to_string()).collect();
        sum += row.iter().map(|&v| u64::from(v)).sum::<u64>();
        out.push_str(&strs.join(" "));
        out.push('\n');
    }
    out.push_str(&format!("SUM {sum}\n"));
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes()).map_err(|e| e.to_string())?;
    lock.flush().map_err(|e| e.to_string())
}

fn gpu_diffuse(w: usize, h: usize, steps: usize, cells: &[u32]) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) =
        pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
            .map_err(|e| format!("device: {e}"))?;

    let size = (w * h * 4) as u64;
    let usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(cells),
        usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage,
        mapped_at_creation: false,
    });
    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&[w as u32, h as u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: dst.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: params.as_entire_binding() },
            ],
        })
    };
    let groups = [make_group(&buf_a, &buf_b), make_group(&buf_b, &buf_a)];

    let gx = (w as u32).div_ceil(16);
    let gy = (h as u32).div_ceil(16);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    for step in 0..steps {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &groups[step % 2], &[]);
        pass.dispatch_workgroups(gx, gy, 1);
    }
    let result = if steps % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let (tx, rx) = std::sync::mpsc::channel();
    readback.slice(..).map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e}"))?;
    rx.recv()
        .map_err(|e| e.to_string())?
        .map_err(|e| format!("map: {e}"))?;
    let data = readback.slice(..).get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn main() {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: heat <input-file>");
        std::process::exit(2);
    };
    if let Err(e) = run(&path) {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

